#A share link giving anyone who holds it access to one My Annotations project.
CREATE TABLE myVariantsShares (
    id int unsigned not null AUTO_INCREMENT,	# Auto-increment primary key
    ownerUser varchar(255) not null,	# Login of the project's owner
    shareToken varchar(64) not null,	# 48-char URL-safe token; holding it is what grants access
    projectId int unsigned not null,	# myVariantsProjects.id of the shared project
    permission tinyint unsigned not null default 0,	# 0=view, 1=edit
    createdAt timestamp not null default CURRENT_TIMESTAMP,	# Timestamp of creation
              #Indices
    PRIMARY KEY(id),
    UNIQUE KEY(shareToken),
    UNIQUE KEY(projectId),
    KEY(ownerUser)
) ENGINE=InnoDB;
